var results = [];
var commands = [];

// ① Waveshare 8CH (Unit-Id 1, FC15 coil, 0-indexed)
commands.push({
    payload: {
        value: [0, 0, 0, 0, 0, 0, 0, 0],
        unitid: 1,
        fc: 15,
        address: 0,
        quantity: 8
    },
    label: 'Waveshare 8CH'
});

// ② Eletechsup 8CH (Unit-Id 2, FC06 register, 1-indexed)
for (var i = 1; i <= 8; i++) {
    commands.push({
        payload: {
            value: 0,
            unitid: 2,
            fc: 6,
            address: i,
            quantity: 1
        },
        label: 'Eletechsup CH' + i
    });
}

var sent = 0;
var total = commands.length;

function sendNext() {
    if (sent >= total) {
        msg.payload = {
            success: true,
            detail: total + '개 명령 전송',
            results: results
        };
        msg.statusCode = 200;
        node.send([null, msg]);
        node.warn('🔄 릴레이 전체 OFF 완료: ' + total + '개 명령');
        return;
    }

    var cmd = commands[sent];
    var m = RED.util.cloneMessage(msg);
    m.payload = cmd.payload;
    results.push(cmd.label + ' → OFF');
    sent++;

    node.send([m, null]);

    if (sent < total) {
        setTimeout(sendNext, 200);
    } else {
        setTimeout(sendNext, 300);
    }
}

sendNext();
return null;
